-- TEST ONLY. Synthetic identities and messages are rolled back, never delivered to real users.
create or replace function pg_temp.chat_suite() returns jsonb language plpgsql security invoker as $suite$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); d uuid:=gen_random_uuid();
  training uuid:=gen_random_uuid(); mid uuid:=gen_random_uuid(); reply uuid:=gen_random_uuid(); bid uuid:=gen_random_uuid();
  first_seq bigint; reply_seq bigint; result jsonb; checks jsonb:='{}'; denied boolean;
begin
  if not exists(select 1 from pg_proc where proname='nh_test_paid' and pronamespace='public'::regnamespace) then raise exception 'TEST project required'; end if;
  begin
    insert into auth.users(id,aud,role) values(a,'authenticated','authenticated'),(b,'authenticated','authenticated'),(c,'authenticated','authenticated'),(d,'authenticated','authenticated');
    insert into public.profiles(id,full_name,role) values(a,'Chat fixture A','athlete'),(b,'Chat fixture B','athlete'),(c,'Chat fixture C','admin'),(d,'Chat fixture D','admin');
    insert into public.weekly_training_plan(id,athlete_id,session_date,category,title) values(training,a,current_date,'trail','Synthetic trail session');
    perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true); perform set_config('role','authenticated',true);
    result:=public.messaging_send(a,mid,'  Pregunta de prueba  ',training); first_seq:=(result->>'seq')::bigint;
    checks:=checks||jsonb_build_object('sender_from_auth',result->>'sender_id'=a::text,'body_trimmed',result->>'body'='Pregunta de prueba','training_snapshot',result->>'training_title'='Synthetic trail session');
    result:=public.messaging_send(a,mid,'Pregunta de prueba',training);
    checks:=checks||jsonb_build_object('retry_idempotent',(result->>'seq')::bigint=first_seq and (select count(*) from public.club_messages where id=mid)=1,'own_read',(select count(*) from public.club_messages)=1);
    denied:=false; begin perform public.messaging_send(a,mid,'Changed',training); exception when sqlstate '22023' then denied:=true; end; checks:=checks||jsonb_build_object('id_reuse_changed_body_denied',denied);
    denied:=false; begin perform public.messaging_send(b,gen_random_uuid(),'Foreign',null); exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('cross_thread_send_denied',denied);
    denied:=false; begin perform public.messaging_send(a,gen_random_uuid(),' ',null); exception when sqlstate '22023' then denied:=true; end; checks:=checks||jsonb_build_object('empty_message_denied',denied);
    denied:=false; begin perform public.messaging_send(a,gen_random_uuid(),E'\n\t',null); exception when sqlstate '22023' then denied:=true; end; checks:=checks||jsonb_build_object('whitespace_message_denied',denied);
    denied:=false; begin perform public.messaging_send(a,gen_random_uuid(),repeat('x',2001),null); exception when sqlstate '22023' then denied:=true; end; checks:=checks||jsonb_build_object('oversized_message_denied',denied);
    denied:=false; begin insert into public.club_messages(id,athlete_id,sender_id,body) values(gen_random_uuid(),a,c,'Forged'); exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('direct_forged_insert_denied',denied);
    denied:=false; begin update public.club_messages set body='Changed' where id=mid; exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('direct_edit_denied',denied);
    denied:=false; begin delete from public.club_messages where id=mid; exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('direct_delete_denied',denied);
    perform set_config('role','postgres',true);
    perform set_config('request.jwt.claims',json_build_object('sub',b,'role','authenticated')::text,true); perform set_config('role','authenticated',true);
    result:=public.messaging_send(b,bid,'Pregunta B',null);
    checks:=checks||jsonb_build_object('other_client_history_hidden',(select count(*) from public.club_messages)=1 and not exists(select 1 from public.club_messages where athlete_id=a));
    denied:=false; begin perform public.messaging_send(b,gen_random_uuid(),'Wrong session',training); exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('foreign_training_context_denied',denied);
    denied:=false; begin perform public.messaging_mark_read(a,first_seq); exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('foreign_receipt_denied',denied);
    result:=public.messaging_inbox(); checks:=checks||jsonb_build_object('client_inbox_isolated',jsonb_array_length(result)=1 and result->0->>'athlete_id'=b::text);
    perform set_config('role','postgres',true);
    perform set_config('request.jwt.claims',json_build_object('sub',c,'role','authenticated')::text,true); perform set_config('role','authenticated',true);
    result:=public.messaging_send(a,reply,'Respuesta del entrenador',training); reply_seq:=(result->>'seq')::bigint;
    perform public.messaging_send(b,gen_random_uuid(),'Respuesta B',null);
    checks:=checks||jsonb_build_object('coach_reads_both_threads',(select count(*) from public.club_messages where athlete_id in(a,b))=4);
    result:=public.messaging_inbox(); checks:=checks||jsonb_build_object('own_sent_messages_not_unread',(select sum((value->>'unread')::bigint) from jsonb_array_elements(result) where value->>'athlete_id' in(a::text,b::text))=2);
    perform public.messaging_mark_read(a,reply_seq);
    result:=public.messaging_inbox(); checks:=checks||jsonb_build_object('coach_receipts_per_thread',(select (value->>'unread')::bigint from jsonb_array_elements(result) where value->>'athlete_id'=a::text)=0 and (select (value->>'unread')::bigint from jsonb_array_elements(result) where value->>'athlete_id'=b::text)=1);
    perform set_config('role','postgres',true);
    perform set_config('request.jwt.claims',json_build_object('sub',d,'role','authenticated')::text,true); perform set_config('role','authenticated',true);
    result:=public.messaging_inbox(); checks:=checks||jsonb_build_object('coach_receipts_independent',(select sum((value->>'unread')::bigint) from jsonb_array_elements(result) where value->>'athlete_id' in(a::text,b::text))=4);
    perform set_config('role','postgres',true);
    perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true); perform set_config('role','authenticated',true);
    result:=public.messaging_inbox(); checks:=checks||jsonb_build_object('client_unread_reply',(result->0->>'unread')::int=1);
    perform public.messaging_mark_read(a,reply_seq+10000); perform public.messaging_mark_read(a,0);
    checks:=checks||jsonb_build_object('receipt_clamped_and_monotonic',(select last_read_seq=reply_seq from public.club_message_reads where athlete_id=a and reader_id=a));
    checks:=checks||jsonb_build_object('only_own_receipts_visible',(select count(*) from public.club_message_reads)=1);
    denied:=false; begin insert into public.club_message_reads values(b,a,100000); exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('direct_receipt_write_denied',denied);
    perform set_config('role','postgres',true);
    perform set_config('request.jwt.claims','{}',true); perform set_config('role','anon',true);
    denied:=false; begin perform public.messaging_inbox(); exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('anon_inbox_denied',denied);
    denied:=false; begin perform 1 from public.club_messages; exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('anon_history_denied',denied);
    denied:=false; begin perform public.messaging_send(a,gen_random_uuid(),'Anonymous',null); exception when insufficient_privilege then denied:=true; end; checks:=checks||jsonb_build_object('anon_send_denied',denied);
    perform set_config('role','postgres',true);
    raise exception using errcode='P0002',message='Rollback synthetic messaging fixtures';
  exception when no_data_found then null;
  end;
  return jsonb_build_object('checks',checks,'passed',(select count(*) from jsonb_each(checks) where value='true'::jsonb),'failed',(select count(*) from jsonb_each(checks) where value<>'true'::jsonb),'remaining_fixture_users',(select count(*) from auth.users where id in(a,b,c,d)),'remaining_fixture_messages',(select count(*) from public.club_messages where athlete_id in(a,b)));
end;
$suite$;
select pg_temp.chat_suite();
